import{_ as a,o as t,c as i,a2 as e}from"./chunks/framework.CNfFRqmr.js";const k=JSON.parse('{"title":"Agent Skills 技术方案","description":"Skills 系统遵循 Progressive Disclosure（渐进式披露） 原则：","frontmatter":{"title":"Agent Skills 技术方案","description":"Skills 系统遵循 Progressive Disclosure（渐进式披露） 原则："},"headers":[],"relativePath":"zh/docs/agent-skills.md","filePath":"zh/docs/agent-skills.md"}'),n={name:"zh/docs/agent-skills.md"};function l(d,s,o,p,r,h){return t(),i("div",null,[...s[0]||(s[0]=[e(`<h1 id="agent-skills-技术方案" tabindex="-1">Agent Skills 技术方案 <a class="header-anchor" href="#agent-skills-技术方案" aria-label="Permalink to &quot;Agent Skills 技术方案&quot;">​</a></h1><h2 id="_1-设计原理-progressive-disclosure" tabindex="-1">1. 设计原理：Progressive Disclosure <a class="header-anchor" href="#_1-设计原理-progressive-disclosure" aria-label="Permalink to &quot;1. 设计原理：Progressive Disclosure&quot;">​</a></h2><p>Skills 系统遵循 <strong>Progressive Disclosure（渐进式披露）</strong> 原则：</p><ul><li><strong>启动时</strong>：只将 skills 的 <code>name</code> + <code>description</code> 索引注入 System Prompt，不加载全文</li><li><strong>运行时</strong>：LLM 根据用户任务判断是否需要某个 skill，通过调用 <code>use_skill</code> 工具按需加载全文</li></ul><p>这样避免了将所有 skill 全文一次性注入 System Prompt 导致的 Token 膨胀，保持上下文窗口的高效利用。</p><h2 id="_2-目录结构" tabindex="-1">2. 目录结构 <a class="header-anchor" href="#_2-目录结构" aria-label="Permalink to &quot;2. 目录结构&quot;">​</a></h2><p>每个 skill 是独立的子目录，目录名即 skill 标识，<code>SKILL.md</code> 是固定文件名：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{workdir}/skills/</span></span>
<span class="line"><span>├── go-coding-standards/</span></span>
<span class="line"><span>│   └── SKILL.md</span></span>
<span class="line"><span>├── debugging-guide/</span></span>
<span class="line"><span>│   └── SKILL.md</span></span>
<span class="line"><span>└── architecture-overview/</span></span>
<span class="line"><span>    └── SKILL.md</span></span></code></pre></div><p>harness9 启动时自动扫描 <code>{workdir}/skills/</code> 下的所有子目录，加载各自的 <code>SKILL.md</code>。</p><h2 id="_3-skill-文件格式" tabindex="-1">3. Skill 文件格式 <a class="header-anchor" href="#_3-skill-文件格式" aria-label="Permalink to &quot;3. Skill 文件格式&quot;">​</a></h2><p>每个 <code>SKILL.md</code> 是标准 Markdown 文件，开头包含 YAML frontmatter：</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">---</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">go-refactor</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">description</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Use when refactoring Go code — team conventions and patterns</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">trigger</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;refactor, clean up, restructure, simplify&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">---</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;"># Go 重构指南</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## 重构前必做</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">1.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 运行 </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\`go vet ./...\`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 确认无静态分析错误</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">2.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 运行 </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\`go test ./...\`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 确认测试全部通过</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">3.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 查看 git diff 确认修改范围</span></span></code></pre></div><h3 id="frontmatter-字段说明" tabindex="-1">frontmatter 字段说明 <a class="header-anchor" href="#frontmatter-字段说明" aria-label="Permalink to &quot;frontmatter 字段说明&quot;">​</a></h3><table tabindex="0"><thead><tr><th>字段</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>name</code></td><td>string</td><td><strong>是</strong></td><td>skill 唯一标识（供 <code>use_skill</code> 工具调用）</td></tr><tr><td><code>description</code></td><td>string</td><td><strong>是</strong></td><td>简短描述，注入 System Prompt 索引，帮助 LLM 判断何时使用</td></tr><tr><td><code>trigger</code></td><td>string</td><td>否</td><td>触发关键词，仅作文档说明，不做自动匹配</td></tr></tbody></table><h2 id="_4-触发方式" tabindex="-1">4. 触发方式 <a class="header-anchor" href="#_4-触发方式" aria-label="Permalink to &quot;4. 触发方式&quot;">​</a></h2><p>Skills 支持两种触发方式：</p><h3 id="_4-1-tool-calling-主要方式" tabindex="-1">4.1 Tool-Calling（主要方式） <a class="header-anchor" href="#_4-1-tool-calling-主要方式" aria-label="Permalink to &quot;4.1 Tool-Calling（主要方式）&quot;">​</a></h3><p>LLM 看到 System Prompt 中的 skills 索引后，自主判断是否需要加载某个 skill，通过调用 <code>use_skill</code> 工具触发：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>System Prompt 末尾（skills 索引）→ LLM 判断适用技能</span></span>
<span class="line"><span>  → tool_use: {name: &quot;use_skill&quot;, arguments: {skill_name: &quot;go-refactor&quot;}}</span></span>
<span class="line"><span>  → 框架加载 SKILL.md 正文，作为 tool_result 返回</span></span>
<span class="line"><span>  → LLM 在完整技能指令下继续执行</span></span></code></pre></div><h3 id="_4-2-斜杠命令-cli-快捷路径" tabindex="-1">4.2 斜杠命令（CLI 快捷路径） <a class="header-anchor" href="#_4-2-斜杠命令-cli-快捷路径" aria-label="Permalink to &quot;4.2 斜杠命令（CLI 快捷路径）&quot;">​</a></h3><p>CLI REPL 模式下，用户可直接输入 <code>/skill-name</code> 触发技能，框架直接加载正文，绕过 LLM 判断：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/go-refactor               → prompt = skill body</span></span>
<span class="line"><span>/go-refactor 清理 main.go  → prompt = skill body + &quot;\\n\\n&quot; + &quot;清理 main.go&quot;</span></span></code></pre></div><blockquote><p>斜杠命令仅在 CLI 模式（非 TTY 管道环境）下支持，TUI 模式下通过 <code>/skill</code> 命令或直接对话激活。</p></blockquote><h2 id="_5-system-prompt-注入效果" tabindex="-1">5. System Prompt 注入效果 <a class="header-anchor" href="#_5-system-prompt-注入效果" aria-label="Permalink to &quot;5. System Prompt 注入效果&quot;">​</a></h2><p>harness9 启动后，System Prompt 末尾会附加 skills 索引：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>## Available Skills</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Use the \`use_skill\` tool to load the full content of any skill when needed.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- go-refactor: Use when refactoring Go code — team conventions and patterns</span></span>
<span class="line"><span>- testing-guide: Use when writing or reviewing tests</span></span>
<span class="line"><span>- deploy-guide: Use when deploying to production</span></span></code></pre></div><h2 id="_6-llm-调用-use-skill-工具" tabindex="-1">6. LLM 调用 use_skill 工具 <a class="header-anchor" href="#_6-llm-调用-use-skill-工具" aria-label="Permalink to &quot;6. LLM 调用 use_skill 工具&quot;">​</a></h2><p>LLM 在判断需要某个 skill 的完整内容时，会发起工具调用：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;use_skill&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;arguments&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;skill_name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;go-refactor&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>工具返回该 skill 文件 frontmatter 之后的完整 body 内容，LLM 随后基于此内容指导任务执行。</p><h2 id="_7-模块实现" tabindex="-1">7. 模块实现 <a class="header-anchor" href="#_7-模块实现" aria-label="Permalink to &quot;7. 模块实现&quot;">​</a></h2><table tabindex="0"><thead><tr><th>模块</th><th>文件</th><th>职责</th></tr></thead><tbody><tr><td><code>skills.Skill</code></td><td><code>internal/skills/skill.go</code></td><td>数据结构 + frontmatter 解析</td></tr><tr><td><code>skills.Index</code></td><td><code>internal/skills/index.go</code></td><td>索引摘要 + 懒加载全文</td></tr><tr><td><code>skills.LoadSkills</code></td><td><code>internal/skills/loader.go</code></td><td>扫描子目录构建 Index</td></tr><tr><td><code>skills.UseSkillTool</code></td><td><code>internal/skills/use_skill_tool.go</code></td><td><code>use_skill</code> 工具实现</td></tr><tr><td><code>context.DefaultPromptBuilder</code></td><td><code>internal/context/builder.go</code></td><td>组装 System Prompt</td></tr></tbody></table><h2 id="_8-错误处理" tabindex="-1">8. 错误处理 <a class="header-anchor" href="#_8-错误处理" aria-label="Permalink to &quot;8. 错误处理&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>行为</th></tr></thead><tbody><tr><td><code>skills/</code> 目录不存在</td><td>返回空 Index，静默跳过</td></tr><tr><td>子目录缺少 <code>SKILL.md</code></td><td>跳过该目录，打印 warn 日志</td></tr><tr><td>skill 文件缺少 <code>name</code> 或 <code>description</code></td><td>跳过该文件，打印 warn 日志</td></tr><tr><td><code>use_skill</code> 调用不存在的 skill</td><td>返回包含可用名称列表的错误信息，LLM 可自愈</td></tr><tr><td>CLI 斜杠命令指向不存在的 skill</td><td>打印错误到 stderr，继续 REPL 循环</td></tr><tr><td><code>AGENTS.md</code> 不存在</td><td>PromptBuilder 跳过该段落</td></tr></tbody></table><h2 id="_9-cli-启动方式" tabindex="-1">9. CLI 启动方式 <a class="header-anchor" href="#_9-cli-启动方式" aria-label="Permalink to &quot;9. CLI 启动方式&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /your/project</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">harness9</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # TTY → TUI，管道/CI → CLI REPL</span></span></code></pre></div>`,36)])])}const g=a(n,[["render",l]]);export{k as __pageData,g as default};
